<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides recognition behavior within the WorkIntel application. */ class Recognition extends Model{public $timestamps=false;protected $fillable=['uuid','workspace_id','recipient_member_id','sender_member_id','type','title','message','points','visible_to_team','recognized_at'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['visible_to_team'=>'boolean','recognized_at'=>'datetime'];}/** Handles the recipient operation for the current WorkIntel workflow. */ public function recipient():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'recipient_member_id');}/** Sends sender information to the configured recipient. */ public function sender():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'sender_member_id');}}
